#include <string.h>
#include <stdlib.h>

void normalize_file_path(char* file) {
    if (file == NULL)
        return;

    char* src = file;
    char* dst = file;
    size_t len = strlen(file);

    // Step 1: Collapse multiple consecutive slashes into a single slash
    while (*src) {
        *dst++ = *src++;

        // If a slash was just copied, skip any subsequent slashes
        if (dst[-1] == '/') {
            while (*src == '/')
                src++;
        }
    }

    // Null-terminate the string after collapsing slashes
    *dst = '\0';

    // Reset pointers for the rest of the operations
    src = file;
    dst = file;

    // Step 2: Remove any leading './' and occurrences of '/.'
    while (*src) {
        if (src[0] == '/' && src[1] == '.') {
            // Skip './' in the path
            src += 2;
            dst++;
            continue;
        }

        // Skip '.' in the path when preceded by a slash
        if (src[0] == '.' && src[1] == '/') {
            src += 2;
            dst++;
            continue;
        }

        *dst++ = *src++;
    }

    // Null-terminate the string after handling '.'
    *dst = '\0';

    // Step 3: Resolve 'xxx/../' by removing the preceding directory
    char* buffer = (char*)malloc(len + 1);
    if (!buffer)
        return;
    buffer[0] = '\0';

    src = file;
    while (*src) {
        // Check for pattern 'xxx/../'
        if (strncmp(src, "/../", 4) == 0) {
            char* base = buffer;
            // Remove the last directory from buffer
            while (base && *base) {
                if (base == buffer || *(base - 1) == '/') {
                    base--;
                } else {
                    base = strrchr(buffer, '/');
                }
            }
            if (base) {
                strcpy(base, src + 4);
            }
            src += 4;
        } else if (strncmp(src, "../", 3) == 0) {
            // Resolve leading '../'
            char* base = buffer;
            if (base == buffer) {
                strcpy(buffer, src);
            } else {
                base = strrchr(buffer, '/');
                if (base) {
                    strcpy(base, src + 2);
                } else {
                    // No slash found, so the path is not absolute
                    strcpy(buffer, src + 2);
                }
            }
            src += 3;
        } else {
            // Copy normal path part
            *dst++ = *src++;
        }
    }

    // Null-terminate the buffer
    *dst = '\0';

    // Step 4: Eliminate any trailing '/..'
    char* last = strrchr(buffer, '/');
    if (last && strncmp(last, "/..", 3) == 0) {
        // Clear the last component of the path
        *last = '\0';
    }

    // Copy the normalized path back to the original string
    strcpy(file, buffer);

    free(buffer);
}

