#define MAX_PATH 1024

void normalize_path(char* file) {
    char result[MAX_PATH];
    char* ptr = file;
    char* res = result;
    char buffer[MAX_PATH];
    char* top = buffer;

    // Step 1: Collapse multiple slashes into a single slash
    while (*ptr) {
        if (*ptr == '/' && (res == result || *(res - 1) == '/')) {
            ptr++;
            continue;
        }
        *res++ = *ptr++;
    }
    *res = '\0';

    // Step 2: Process the path and resolve directories
    char* token = strtok(result, "/");
    while (token != NULL) {
        if (strcmp(token, ".") != 0 && strcmp(token, "") != 0) {
            if (strcmp(token, "..") == 0) {
                // Step 3: Remove the previous directory for '..'
                if (top > buffer) {
                    // Move back to the last slash
                    while (top > buffer && *(top - 1) != '/') {
                        top--;
                    }
                    if (top > buffer) {
                        top--;
                    }
                }
            } else {
                // Copy the directory name
                strcpy(top, token);
                top += strlen(token);
                if (*(top - 1) != '/') {
                    *top++ = '/';
                }
            }
        }
        token = strtok(NULL, "/");
    }

    // Step 4: Remove the trailing slash if present
    if (top > buffer && *(top - 1) == '/') {
        top--;
    }

    *top = '\0';

    // Copy the result back to the original file buffer
    strcpy(file, buffer);
}

#include <string.h>
#include <stdlib.h>

void normalize_path(char* file) {
    if (file == NULL) {
        return;
    }

    // Use a buffer to build the normalized path
    char* buffer = (char*)malloc(strlen(file) + 1);
    if (buffer == NULL) {
        return; // Out of memory
    }

    buffer[0] = '\0';
    char* token = strtok(file, "/");
    while (token != NULL) {
        if (strcmp(token, ".") != 0 && strcmp(token, "") != 0) {
            if (strcmp(token, "..") == 0) {
                // Remove the last component if it's not empty
                char* lastSlash = strrchr(buffer, '/');
                if (lastSlash != NULL) {
                    *lastSlash = '\0';
                } else if (buffer[0] != '\0') {
                    buffer[0] = '\0';
                }
            } else {
                // Append the current component
                if (buffer[0] == '\0') {
                    // No leading slash for the root
                    strcat(buffer, token);
                } else {
                    strcat(buffer, "/");
                    strcat(buffer, token);
                }
            }
        }
        token = strtok(NULL, "/");
    }

    // Replace the original string with the normalized path
    strcpy(file, buffer);
    free(buffer);
}

