#define MAX_PATH 4096

void normalize_path(char *file) {
    char buffer[MAX_PATH] = "";
    char *token = file;
    char *next_token;
    char *result = buffer;

    while (*token) {
        // Skip multiple slashes
        if (*token == '/') {
            while (*(token + 1) == '/') {
                token++;
            }
        }

        // Handle ./
        if (*token == '.' && *(token + 1) == '/') {
            token += 2;
            continue;
        }

        // Handle /
        if (*token == '/') {
            result++;
            *result = *token++;
            continue;
        }

        // Handle . in the path
        if (*token == '.' && *(token + 1) == '.' && *(token + 2) == '/') {
            // Remove the previous directory
            while (result > buffer && *(result - 1) != '/') {
                result--;
            }
            token += 3;
            continue;
        }

        // Copy other characters
        *result++ = *token++;
    }

    // Ensure the path ends with a null terminator
    *result = '\0';

    // Copy the normalized path back to the input
    strcpy(file, buffer);
}

#include <string.h>
#include <stdlib.h>

void normalize_path(char* file) {
    if (file == NULL || *file == '\0') {
        *file = '\0';
        return;
    }

    char* src = file;
    char* dest = file;

    // Collapse multiple slashes into a single slash
    while (*src != '\0') {
        if (*src == '/' && dest > file && *dest == '/') {
            src++;
        } else {
            *dest++ = *src++;
        }
    }

    *dest = '\0';  // Null-terminate the string

    // Process the path to handle . and ..
    char* temp = malloc(strlen(file) + 1);
    if (temp == NULL) {
        return;  // Allocation failed, cannot proceed
    }

    strcpy(temp, file);
    char* token;
    char* path_tokens = NULL;
    char* current_token = NULL;
    int depth = 0;

    // Split path into tokens based on '/'
    for (int i = 0; temp[i] != '\0'; i++) {
        if (temp[i] == '/') {
            temp[i] = '\0';
            token = &temp[i];
            if (token == path_tokens) {
                path_tokens = NULL;
            }
            if (path_tokens == NULL && i == 0) {
                path_tokens = token;
            }
        }
    }

    dest = file;
    char* start = temp;

    while ((current_token = strtok(start, "/")) != NULL) {
        if (strcmp(current_token, ".") == 0) {
            // Skip current directory reference
        } else if (strcmp(current_token, "..") == 0) {
            // Handle parent directory reference
            if (depth > 0) {
                depth--;
                // Skip the previous directory
                while (dest > file && dest[-1] != '/') {
                    dest--;
                }
                if (dest > file) {
                    dest--;
                }
            }
        } else {
            // Add the directory name
            int len = strlen(current_token);
            if (len > 0) {
                if (dest > file) {
                    *dest++ = '/';
                }
                memcpy(dest, current_token, len);
                dest += len;
                depth++;
            }
        }

        start = NULL;
    }

    // Remove trailing slash if needed
    if (dest > file && dest[-1] == '/') {
        dest--;
    }

    // Eliminate trailing '..'
    if (dest - 2 >= file && dest[-1] == '.' && dest[-2] == '.') {
        dest -= 2;
        while (dest > file && dest[-1] != '/') {
            dest--;
        }
        if (dest > file && dest[-1] == '/') {
            dest--;
        }
    }

    *dest = '\0';  // Null-terminate the result

    free(temp);
}
